WITH cleaned AS (SELECT *, DATE_TRUNC('WEEK', txn_time) AS txn_time_period, UPPER(merchant) AS merchant_upper FROM transactions WHERE merchant IS NOT NULL), flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM cleaned), sessions_transactions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT DATE_TRUNC('MONTH', txn_time) AS activity_month, DATE_TRUNC('QUARTER', txn_time) AS quarter_start, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS span_minutes, MIN(new_group_flag) AS min_new_group_flag, COUNT(CASE WHEN merchant = 'Amazon' THEN 1 END) AS amazon_count FROM sessions_transactions GROUP BY DATE_TRUNC('MONTH', txn_time), DATE_TRUNC('QUARTER', txn_time) HAVING (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 > 0
